  function welcomePanel(state){if(!state.showEntryModes)return storyOpening(state);const modes=[['guided','Geführt','Alle Entscheidungen Schritt für Schritt treffen.','9 Schritte'],['quick','Schnellstart','Ziel und Zeitraum festlegen, Gestaltung wählen, loslegen.','5 Schritte'],['ai','Mit Luvia AI','Ein Wunsch, eine Zeitwahl, danach der vollständige Reiseentwurf.','6 Schritte']];return `<article class="ftc-panel ftc-welcome"><div class="ftc-story"><span class="ftc-kicker">Euer nächstes Kapitel</span><h1>Eine Richtung. <em>Euer eigener Weg.</em></h1><p>Ihr entscheidet, wie viel ihr selbst gestalten möchtet. Eure Eingaben bleiben beim Wechsel erhalten.</p><div class="ftc-entry-modes">${modes.map(([id,label,copy,count])=>`<button type="button" data-ftc-entry-mode="${id}" class="${state.data.entryMode===id?'is-selected':''}" aria-pressed="${state.data.entryMode===id}"><i>${id==='guided'?'⌁':id==='quick'?'↝':'✦'}</i><span><strong>${label}</strong><small>${copy}</small><b>${count}</b></span></button>`).join('')}</div><div class="ftc-scope-line"><span>Anfrage bleibt flüchtig</span><span>Reisewünsche gelten für diese Reise</span><span>Profiländerungen brauchen Bestätigung</span></div></div><aside class="ftc-world-interactive">${window.LuviaComposerTravelWorld?.markup?.()||''}</aside></article>`;}
  function identityPanel(state){return `<article class="ftc-panel"><header class="ftc-copy"><span class="ftc-kicker">Reiseidentität</span><h1>Wie soll diese Reise heißen?</h1><p>Ein Name, eine kleine Zeile und ein Zeichen – alles später änderbar.</p></header><div class="ftc-form"><label><span>Reisename</span><input data-ftc-field="title" maxlength="80" value="${esc(state.data.title)}" placeholder="Unser Sommer am Meer" autocomplete="off"></label><label><span>Unterzeile</span><input data-ftc-field="subtitle" maxlength="120" value="${esc(state.data.subtitle)}" placeholder="Zeit für uns, ohne engen Takt" autocomplete="off"></label><fieldset class="ftc-symbols"><legend>Euer Zeichen</legend>${SYMBOLS.map(symbol=>`<button type="button" data-ftc-symbol="${symbol}" class="${state.data.symbol===symbol?'is-selected':''}" aria-pressed="${state.data.symbol===symbol}">${symbol}</button>`).join('')}</fieldset></div></article>`;}
