  function peoplePanel(state){const invite=state.data.participantPlan==='invite-after-creation';return `<article class="ftc-panel"><header class="ftc-copy"><span class="ftc-kicker">Gemeinsam reisen</span><h1>Wie möchtet ihr starten?</h1><p>Entscheidet nur, was direkt nach der Reiseerstellung passiert. Menschen und Rollen werden erst im anschließenden Einladungsschritt festgelegt.</p></header><div class="ftc-date-mode" role="radiogroup" aria-label="Reisegruppe starten"><button type="button" data-ftc-people="solo-first" class="${!invite?'is-selected':''}" aria-pressed="${!invite}"><i>◌</i><strong>Nur für mich starten</strong><small>Die Reise bleibt privat. Einladen geht jederzeit später.</small></button><button type="button" data-ftc-people="invite-after-creation" class="${invite?'is-selected':''}" aria-pressed="${invite}"><i>◎</i><strong>Danach Menschen einladen</strong><small>Nach dem Erstellen öffnet sich der Einladungsschritt.</small></button></div><div class="ftc-owner-note"><i>${invite?'→':'✓'}</i><span><strong>${invite?'Als Nächstes: Einladungen':'Privater Start'}</strong><small>${invite?'Bis jemand eine Einladung annimmt, bleibt die Reise geschützt.':'Nur du siehst die Reise. Diese Entscheidung ist später änderbar.'}</small></span></div></article>`;}
  function modulesPanel(state){return `<article class="ftc-panel"><header class="ftc-copy"><span class="ftc-kicker">Reisebausteine</span><h1>Was soll euch von Anfang an begleiten?</h1><p>Wählt die Bereiche, die ihr auf eurer Reise nutzen möchtet. Ihr könnt eure Auswahl später ändern.</p></header><div class="ftc-module-grid">${MODULES.map(([id,icon,label,copy])=>{const on=state.data.modules.includes(id);return `<button type="button" data-ftc-module="${id}" class="${on?'is-selected':''}" aria-pressed="${on}"><i>${icon}</i><span><strong>${label}</strong><small>${copy}</small></span><b>${on?'✓':'+'}</b></button>`}).join('')}</div></article>`;}
  function briefPanel(state){const p=state.data.tripPreferences||{};return `<article class="ftc-panel"><header class="ftc-copy"><span class="ftc-kicker">Anfrage an Luvia AI</span><h1>Was soll eure Reise können?</h1><p>Schreibt euren Wunsch kurz auf. Luvia beginnt danach selbstständig mit dem Entwurf und fragt nur nach, wenn eine wichtige Angabe wirklich fehlt.</p></header><div class="ftc-brief-layout"><label class="ftc-brief-field"><span>Eure Wünsche in eigenen Worten</span><textarea data-ftc-field="requestBrief" maxlength="1200" placeholder="Wir möchten viel am Wasser sein, ruhig frühstücken, zwei besondere Abende erleben und nicht jeden Tag durchplanen.">${esc(state.data.requestBrief)}</textarea><small>${state.data.requestBrief.length}/1200 · gilt nur für diese Reise</small></label><section class="ftc-trip-preferences"><div><span>Schwerpunkte dieser Reise</span><div class="ftc-chip-grid">${TRIP_INTERESTS.map(([id,label])=>{const on=(p.interests||[]).includes(id);return `<button type="button" data-ftc-trip-interest="${id}" class="${on?'is-selected':''}" aria-pressed="${on}">${label}</button>`}).join('')}</div></div><div><span>Budgetgefühl dieser Reise</span><div class="ftc-chip-grid is-budget">${BUDGETS.map(([id,label])=>`<button type="button" data-ftc-budget="${id}" class="${p.budgetLevel===id?'is-selected':''}" aria-pressed="${p.budgetLevel===id}">${label}</button>`).join('')}</div></div><div><span>Wie viel möchtet ihr erleben?</span><div class="ftc-chip-grid">${[['slow','Viel Freiraum'],['balanced','Gute Mischung'],['active','Viel entdecken']].map(([id,label])=>`<button type="button" data-ftc-pace="${id}" aria-pressed="${p.pace===id}" class="${p.pace===id?'is-selected':''}">${label}</button>`).join('')}</div></div><button type="button" class="ftc-durable-choice ${state.data.durablePreferenceProposal.requested?'is-selected':''}" data-ftc-durable aria-pressed="${state.data.durablePreferenceProposal.requested}"><i>${state.data.durablePreferenceProposal.requested?'✓':'+'}</i><span><strong>Später als Profilvorliebe prüfen</strong><small>Luvia darf nach der Reiseerstellung eine getrennte Bestätigung anbieten. Ohne diese Bestätigung bleibt euer Profil unverändert.</small></span></button></section></div></article>`;}
