      const key=button.dataset.ftcTripInterest?'interests:'+button.dataset.ftcTripInterest:button.dataset.ftcTravelOption||(button.dataset.ftcMix?'mix:'+button.dataset.ftcMix:button.dataset.ftcPace?'pace:'+button.dataset.ftcPace:'budgetLevel:'+button.dataset.ftcBudget),[g,v]=key.split(':');
