    if(step==='interests')return `<article class="ftc-panel lx-single-question"><div class="lx-question-count">1 von 6</div><div class="lx-tray-title">Was möchtet ihr dort erleben?</div><p class="lx-sub">Diese Auswahl steuert die Place-Kategorien.</p><div class="lx-choices lx-primary-choices">${TRIP_INTERESTS.map(([id,label])=>`<button type="button" class="lx-chip" data-ftc-trip-interest="${id}" aria-pressed="${(p.interests||[]).includes(id)}">${label}</button>`).join('')}</div></article>`;
    if(step==='mix')return `<article class="ftc-panel lx-single-question"><div class="lx-question-count">2 von 6</div><div class="lx-tray-title">Wie sollen sich eure Wünsche mischen?</div><p class="lx-sub">Luvia verteilt die gewählten Kategorien über die gesamte Reise.</p><div class="lx-choices lx-primary-choices">${[['balanced','Ausgewogen','Jeder Schwerpunkt bekommt Raum.'],['favorites','Favoriten zuerst','Eure ersten Wünsche kommen häufiger vor.'],['surprising','Mehr Abwechslung','Bewährtes trifft auf einzelne Überraschungen.']].map(([id,label,copy])=>`<button type="button" class="lx-chip lx-mix-choice" data-ftc-mix="${id}" aria-pressed="${p.mix===id}"><strong>${label}</strong><small>${copy}</small></button>`).join('')}</div></article>`;
    if(step==='pace')return `<article class="ftc-panel lx-single-question"><div class="lx-question-count">3 von 6</div><div class="lx-tray-title">Wie voll darf ein Tag werden?</div><p class="lx-sub">Von drei ruhigen bis vier lebendigen Reisemomenten.</p><div class="lx-choices lx-primary-choices">${[['slow','Luftig'],['balanced','Ausgefüllt'],['active','Intensiv']].map(([id,label])=>`<button type="button" class="lx-chip" data-ftc-pace="${id}" aria-pressed="${p.pace===id}">${label}</button>`).join('')}</div></article>`;
    if(step==='mobility')return `<article class="ftc-panel lx-single-question"><div class="lx-question-count">4 von 6</div><div class="lx-tray-title">Wie weit dürfen gute Erlebnisse auseinanderliegen?</div><p class="lx-sub">Diese Wahl steuert Suchradius, Verkehrsmittel und wie viele Stadtteile Luvia einbezieht.</p><div class="lx-choices lx-primary-choices lx-mobility-choices">${[['near_walk','Nah und zu Fuß','Kompakter Radius, kurze Wege und möglichst wenig Umsteigen.'],['city_transit','Stadt mit Bus & Bahn','Mehrere Viertel und die Küste gehören dazu, wenn sie gut erreichbar sind.'],['wide_taxi_car','Weitläufig entdecken','Auch weitere Viertel und Ausflüge; Taxi, Fahrdienst oder Auto sind in Ordnung.']].map(([id,label,copy])=>`<button type="button" class="lx-chip lx-mix-choice" data-ftc-movement="${id}" aria-pressed="${p.movementStyle===id}"><strong>${label}</strong><small>${copy}</small></button>`).join('')}</div></article>`;
