    if(step==='brief')return `<article class="ftc-panel lx-single-question"><div class="lx-tray-title">Gebt Luvia die Zügel.</div><p class="lx-sub">Ein Wunsch genügt. Profilvorlieben, Reiseziel und Zeitraum gelten automatisch mit.</p><label class="lx-free-text"><span>Wie soll eure Reise werden?</span><textarea data-ftc-field="requestBrief" maxlength="1200" placeholder="Zum Beispiel: Plant uns ruhige Tage am Meer, kleine Cafés, Natur und zwei besondere Abende. Lasst genug Freiraum.">${esc(d.requestBrief)}</textarea></label><div class="lx-ai-promise"><i>✦</i><span><strong>Luvia plant die ganze Reise</strong><small>Tage, passende Orte und Reihenfolge werden als überprüfbarer Entwurf aufgebaut.</small></span></div></article>`;
